-- 목적: "2026년 1회 정보처리기사 실기 (AI 커스텀)" 시험을 신규 생성한다.
-- 배경: 기존 2026년 1회 기출 문항은 저작권 문제로 서비스 활용이 어려워, 동일 개념만
--       유지하고 코드 로직·문제 구성·값을 모두 새로 설계한 AI 커스텀 20문항으로 재구성한다.
--       (특히 CODE 문항은 원본 코드 골격을 재사용하지 않고 전혀 다른 코드로 같은 개념을 검증한다.)
--       정답은 CODE 유형 실행 결과를 직접 계산·검증했고, 단답은 기존 채점 규칙
--       (콤마/슬래시 다중값·열거 마커·괄호 대체표기·|| 대체정답)에 맞춰 작성했다.
-- 대상: exams(신규 1행) + questions(신규 20행, exam_id 연결). 기존 데이터는 손대지 않는다.
-- 재실행 안전: 동일 제목 시험이 있으면 재삽입하지 않고, 이미 문항이 있으면 재삽입하지 않는다.
-- id는 두 테이블 모두 GENERATED BY DEFAULT AS IDENTITY이므로 명시하지 않고 자동 생성한다.

BEGIN;

INSERT INTO exams (created_at, del_yn, order_no, question_mode, title, created_by)
SELECT now(), 'N', (SELECT COALESCE(MAX(order_no), 0) + 1 FROM exams), 'SEQUENTIAL',
       '2026년 1회 정보처리기사 실기 (AI 커스텀)', 1
WHERE NOT EXISTS (
    SELECT 1 FROM exams WHERE title = '2026년 1회 정보처리기사 실기 (AI 커스텀)' AND del_yn = 'N'
);

INSERT INTO questions (exam_id, seq, question_type, instruction, content, code, language, answer, explanation)
SELECT e.id, v.seq, v.qt, v.instr, v.content, v.code, v.lang, v.answer, v.expl
FROM (SELECT id FROM exams WHERE title = '2026년 1회 정보처리기사 실기 (AI 커스텀)' AND del_yn = 'N') e,
LATERAL (VALUES
(1, 'CODE',
