 $q$#include <stdio.h>

double maxVal(int p[], int len) {
    int mx = p[0];
    for (int i = 1; i < len; i++)
        if (p[i] > mx) mx = p[i];
    return (double) mx;
}

double minVal(int *p, int len) {
    int mn = *p;
    for (int i = 1; i < len; i++)
        if (*(p + i) < mn) mn = *(p + i);
    return (double) mn;
}

int main() {
    int arr[6] = {34, 78, 12, 90, 45, 67};
    printf("%.1f", (maxVal(arr, 6) + minVal(arr, 6)) / 2);
    return 0;
}$q$,
